<?php
require_once '../includes/role.php'; requireRole('admin'); require_once '../config/database.php'; require_once '../includes/csrf.php';
$error='';$success='';
$q=trim($_GET['q']??''); $filterStatus=$_GET['status']??'';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();
 $action=$_POST['action']??'';$id=(int)($_POST['id']??0);
 if($action==='add'){
  $name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$phone=trim($_POST['phone']??'');$specialization=trim($_POST['specialization']??'');$password=$_POST['password']??'';
  if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<6)$error='Nama, email valid, dan password minimal 6 karakter wajib diisi.';
  else {try{$pdo->beginTransaction();$s=$pdo->prepare('SELECT id FROM users WHERE email=?');$s->execute([$email]);if($s->fetch())throw new Exception('Email sudah digunakan.');$s=$pdo->prepare("INSERT INTO users(name,email,password,phone,role) VALUES(?,?,?,?, 'mechanic')");$s->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),$phone!==''?$phone:null]);$uid=(int)$pdo->lastInsertId();$s=$pdo->prepare('INSERT INTO mechanics(user_id,specialization,status) VALUES(?,?,?)');$s->execute([$uid,$specialization!==''?$specialization:null,'available']);$pdo->commit();$success='Mekanik berhasil ditambahkan.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=servisku_error_message($e);}}
 }elseif($action==='status'&&$id){$status=$_POST['status']??'available';if(!in_array($status,['available','busy','inactive'],true))$error='Status tidak valid.';else{$s=$pdo->prepare("SELECT COUNT(*) FROM bookings WHERE mechanic_id=? AND status IN ('confirmed','waiting','in_progress')");$s->execute([$id]);$activeJobs=(int)$s->fetchColumn();if($activeJobs>0 && $status!=='busy')$error='Mekanik masih memiliki pekerjaan aktif. Selesaikan atau batalkan booking terlebih dahulu.';else{$s=$pdo->prepare('UPDATE mechanics SET status=? WHERE id=?');$s->execute([$status,$id]);$success='Status mekanik diperbarui.';}}}
}
$sql="SELECT m.id,m.specialization,m.status,u.name,u.email,u.phone,COUNT(b.id) jobs FROM mechanics m JOIN users u ON u.id=m.user_id LEFT JOIN bookings b ON b.mechanic_id=m.id AND b.status NOT IN ('waiting_payment','paid','cancelled') WHERE 1=1"; $params=[]; if($q!==''){ $sql.=" AND (u.name LIKE ? OR u.email LIKE ? OR m.specialization LIKE ?)"; $like="%$q%"; $params=[$like,$like,$like]; } if(in_array($filterStatus,['available','busy','inactive'],true)){ $sql.=" AND m.status=?"; $params[]=$filterStatus; } $sql.=" GROUP BY m.id ORDER BY u.name"; $stmt=$pdo->prepare($sql); $stmt->execute($params); $mechanics=$stmt->fetchAll();
$pageTitle='Data Mekanik'; require '../includes/admin_header.php';
?>
<?php if($error): ?><div class="alert"><?= htmlspecialchars($error) ?></div><?php endif; ?><?php if($success): ?><div class="success"><?= htmlspecialchars($success) ?></div><?php endif; ?>
<div class="two-column"><section class="panel"><div class="panel-heading"><h2>Tambah Mekanik</h2></div><form method="post" class="compact-form"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrf_token())?>"><input type="hidden" name="action" value="add"><label>Nama<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Telepon<input name="phone"></label><label>Spesialisasi<input name="specialization" placeholder="Mesin, kelistrikan, dll."></label><label>Password<input type="password" name="password" minlength="6" required></label><button type="submit">Tambah Mekanik</button></form></section>
<section class="panel"><div class="panel-heading"><h2>Daftar Mekanik</h2></div><form method="get" class="admin-filter-form"><input type="search" name="q" value="<?= htmlspecialchars($q) ?>" placeholder="Cari nama, email, atau spesialisasi..."><select name="status"><option value="">Semua status</option><option value="available" <?= $filterStatus==='available'?'selected':'' ?>>Available</option><option value="busy" <?= $filterStatus==='busy'?'selected':'' ?>>Busy</option><option value="inactive" <?= $filterStatus==='inactive'?'selected':'' ?>>Inactive</option></select><button class="small" type="submit">Filter</button><a class="button small secondary" href="mechanics.php">Reset</a></form><div class="table-wrap"><table class="data-table"><thead><tr><th>Mekanik</th><th>Spesialisasi</th><th>Pekerjaan Aktif</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($mechanics as $m): ?><tr><td><strong><?= htmlspecialchars($m['name']) ?></strong><small><?= htmlspecialchars($m['email']) ?></small></td><td><?= htmlspecialchars($m['specialization']??'-') ?></td><td><?= $m['jobs'] ?></td><td><span class="badge badge-<?= $m['status'] ?>"><?= $m['status'] ?></span></td><td><form method="post" class="inline-form"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrf_token())?>"><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?= $m['id'] ?>"><select name="status"><option <?= $m['status']==='available'?'selected':'' ?>>available</option><option <?= $m['status']==='busy'?'selected':'' ?>>busy</option><option <?= $m['status']==='inactive'?'selected':'' ?>>inactive</option></select><button class="small" type="submit">Simpan</button></form></td></tr><?php endforeach; ?></tbody></table></div></section></div>
<?php require '../includes/admin_footer.php'; ?>
